package com.bulletin.app;
import org.junit.Test;
import static org.junit.Assert.*;
public class CompletionVisualsTest {
    @Test public void backgroundGainsYellowOverFiveCompletionsAndResetsWithZero(){int base=0xff083033;assertEquals(base,CompletionVisuals.completedBackground(base,0));int prior=base;for(int i=1;i<=5;i++){int next=CompletionVisuals.completedBackground(base,i);assertTrue(((next>>16)&255)>((prior>>16)&255));assertTrue(((next>>8)&255)>((prior>>8)&255));assertTrue((next&255)<(prior&255));prior=next;}assertEquals(0xff4d4500,prior);assertEquals(prior,CompletionVisuals.completedBackground(base,10));}
    @Test public void outlineMovesTowardBrightYellowOverFiveDailyCompletions(){int base=0xff32a0bd;assertEquals(base,CompletionVisuals.completedOutline(base,0));int previousBlue=256;for(int count=0;count<=5;count++){int color=CompletionVisuals.completedOutline(base,count);assertTrue((color&255)<previousBlue);previousBlue=color&255;}assertEquals(0xffffff00,CompletionVisuals.completedOutline(base,5));assertEquals(0xffffff00,CompletionVisuals.completedOutline(base,50));assertEquals(base,CompletionVisuals.completedOutline(base,-1));}
    @Test public void heldWaveGrowsAndCollapsesBeforeTheCheck(){assertEquals(0,CompletionVisuals.waveGrowth(0),0);assertTrue(CompletionVisuals.waveGrowth(1600)>CompletionVisuals.waveGrowth(400));assertTrue(CompletionVisuals.waveGrowth(10000)<=1);assertEquals(0,CompletionVisuals.collapseProgress(0),0);assertEquals(1,CompletionVisuals.collapseProgress(CompletionVisuals.COLLAPSE_MILLIS),0);assertEquals(0,CompletionVisuals.checkProgress(-CompletionVisuals.COLLAPSE_MILLIS),0);}
    @Test public void pressSquashesThenSpringsPastRestAndSettles(){assertEquals(0,CompletionVisuals.pressAmount(0),0);assertEquals(1,CompletionVisuals.pressAmount(80),0);assertEquals(1,CompletionVisuals.springAmount(0),0);assertTrue(CompletionVisuals.springAmount(100)<0);assertEquals(0,CompletionVisuals.springAmount(CompletionVisuals.SPRING_MILLIS),0);}
    @Test public void visibleRowsFitAvailableSpaceAndRetainRoomForToday(){assertEquals(13,CompletionVisuals.visibleHistoryRows(13,626,42,80));assertEquals(10,CompletionVisuals.visibleHistoryRows(13,500,42,80));assertEquals(2,CompletionVisuals.visibleHistoryRows(13,200,42,80));assertEquals(0,CompletionVisuals.visibleHistoryRows(13,60,42,80));assertEquals(3,CompletionVisuals.visibleHistoryRows(3,1000,42,80));}
    @Test public void windowContainsFourteenCalendarDaysIncludingToday(){assertEquals(87,CompletionVisuals.firstDay(100,1));assertEquals(14,100-CompletionVisuals.firstDay(100,1)+1);assertEquals(97,CompletionVisuals.firstDay(100,97));assertEquals(100,CompletionVisuals.firstDay(100,110));}
    @Test public void checkInterpolatesSmoothlyAndFinishesAtTwoHundredMilliseconds(){assertEquals(0,CompletionVisuals.checkProgress(-1),0);assertEquals(.15625f,CompletionVisuals.checkProgress(50),.0001f);assertEquals(.5f,CompletionVisuals.checkProgress(100),.0001f);assertEquals(.84375f,CompletionVisuals.checkProgress(150),.0001f);assertEquals(1,CompletionVisuals.checkProgress(200),0);assertEquals(1,CompletionVisuals.checkProgress(1000),0);}
    @Test public void rewardFadesInAndOutOverTwoHundredMillisecondsWithinTwoSeconds(){assertEquals(0,CompletionVisuals.rewardAlpha(0),0);assertEquals(.5f,CompletionVisuals.rewardAlpha(100),0);assertEquals(1,CompletionVisuals.rewardAlpha(200),0);assertEquals(1,CompletionVisuals.rewardAlpha(1800),0);assertEquals(.5f,CompletionVisuals.rewardAlpha(1900),0);assertEquals(0,CompletionVisuals.rewardAlpha(2000),0);assertEquals(0,CompletionVisuals.rewardAlpha(2100),0);}
}
